def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    color = grid[points[0][0]][points[0][1]]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    for c in range(c0, c1 + 1):
        if grid[r0][c] == background:
            out[r0][c] = 2
        if grid[r1][c] == background:
            out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if grid[r][c0] == background:
            out[r][c0] = 2
        if grid[r][c1] == background:
            out[r][c1] = 2
    return out
